-- Cloudy: the operation queue and state machine, pending -> sent -> running -> ok | failed | timeout.
-- id IS the op_id the control plane signs, so a retried enqueue and a re-sent op are the same row.
ALTER TABLE operations ADD CONSTRAINT operations_status_check CHECK (status IN ('pending', 'sent', 'running', 'ok', 'failed', 'timeout'));
ALTER TABLE operations ADD CONSTRAINT operations_executor_check CHECK (executor IN ('agent', 'control_plane'));
-- params is text, not jsonb: the control plane signs the exact bytes that were queued, and jsonb
-- would re-order and re-space keys on the way back out. The check still requires a JSON object.
ALTER TABLE operations ADD CONSTRAINT operations_params_object CHECK (jsonb_typeof(params::jsonb) = 'object');
CREATE INDEX operations_queue_idx ON operations (status, created_at) WHERE status IN ('pending', 'sent', 'running');
CREATE INDEX operations_server_idx ON operations (server_id, created_at);
CREATE INDEX operations_team_idx ON operations (team_id, created_at);
